from itertools import combinations

def turan_graph(n: int, p: int) -> set[frozenset[int]]:
    assert p >= 1
    return {frozenset((u, v)) for u, v in combinations(range(n), 2)
            if u % p != v % p}

from itertools import combinations

def greedy_triangle_removal(graph, n):
    def is_tri(h,a,b,c):
        return all(frozenset(e) in h for e in [(a,b),(a,c),(b,c)])
    h = set(graph); removed = 0
    for a,b,c in combinations(range(n),3):
        if is_tri(graph,a,b,c) and is_tri(h,a,b,c):
            h.discard(frozenset((a,b))); removed += 1
    return h, removed

def mantel_ceiling(n: int) -> int:
    return n * n // 4

def forces_triangle(n: int, m: int) -> bool:
    return m > mantel_ceiling(n)
